insert into units (id, subject_id, title, description, sort_order) values
  ('ry-coxluq', 'riyaziyyat', 'Çoxluqlar', 'Çoxluq anlayışı, elementlər (∈, ∉), çoxluğun verilmə üsulları, alt çoxluq (⊂), kəsişmə (∩) və birləşmə (∪).', 7)
insert into lessons (id, unit_id, title, intro, visual, sections, sort_order) values
  ('ry-cox-l1', 'ry-coxluq', 'Çoxluq və onun elementləri', 'Çoxluq nədir, element nədir və çoxluq necə yazılır?', null, '[{"heading":"Çoxluq nədir?","body":"Ümumi bir əlaməti olan obyektlərin (əşyaların, ədədlərin, hərflərin) toplusuna çoxluq deyilir. Məsələn: həftənin günləri çoxluğu, cüt ədədlər çoxluğu, sinifdəki şagirdlər çoxluğu."},{"heading":"Element","body":"Çoxluğu təşkil edən hər bir obyektə onun elementi deyilir. «a elementi A çoxluğuna aiddir» → a ∈ A. «Aid deyil» → a ∉ A. Məsələn A = {2, 4, 6} olsa, 4 ∈ A, amma 5 ∉ A."},{"heading":"Yazılış","body":"Çoxluq fiqurlu (əyri) mötərizə { } ilə yazılır, elementlər vergüllə ayrılır: A = {1, 2, 3}. Elementlərin sırası vacib deyil: {1, 2, 3} = {3, 1, 2}."},{"heading":"Boş çoxluq","body":"Heç bir elementi olmayan çoxluğa boş çoxluq deyilir və ∅ (və ya { }) ilə işarələnir. Məsələn, «10-dan böyük birrəqəmli ədədlər» çoxluğu boşdur."}]'::jsonb, 0),
  ('ry-cox-l2', 'ry-coxluq', 'Çoxluğun verilmə üsulları və alt çoxluq', 'Çoxluğu necə vermək olar və alt çoxluq nədir?', null, '[{"heading":"Sadalama üsulu","body":"Çoxluğun bütün elementlərini bir-bir mötərizə içində yazırıq: A = {2, 4, 6, 8}. Bu, sadalama (siyahı) üsuludur."},{"heading":"Xassə (əlamət) ilə vermə","body":"Bəzən elementləri ümumi əlaməti ilə təsvir edirik: «A — 10-dan kiçik cüt natural ədədlər çoxluğudur». Bu, sözlə (xassə ilə) verilmədir."},{"heading":"Alt çoxluq","body":"B çoxluğunun hər elementi A çoxluğunda varsa, B çoxluğu A-nın alt çoxluğudur: B ⊂ A. Məsələn {2, 4} ⊂ {2, 4, 6, 8}."},{"heading":"Bərabər çoxluqlar","body":"Elementləri eyni olan iki çoxluq bərabərdir: A = B. Boş çoxluq (∅) istənilən çoxluğun alt çoxluğudur."}]'::jsonb, 1),
  ('ry-cox-l3', 'ry-coxluq', 'Çoxluqların kəsişməsi (∩)', 'İki çoxluğun ortaq elementləri — kəsişmə.', null, '[{"heading":"Kəsişmə nədir?","body":"İki çoxluğun HƏR İKİSİNDƏ olan (ortaq) elementlərdən düzələn çoxluğa onların kəsişməsi deyilir və A ∩ B ilə işarələnir."},{"heading":"Nümunə","body":"A = {1, 2, 3, 4}, B = {3, 4, 5, 6} olsa, ortaq elementlər 3 və 4-dür. Deməli A ∩ B = {3, 4}."},{"heading":"Kəsişməyən çoxluqlar","body":"Ortaq elementləri olmayan çoxluqların kəsişməsi boş çoxluqdur: A ∩ B = ∅. Məsələn, cüt və tək ədədlər çoxluqlarının ortaq elementi yoxdur."}]'::jsonb, 2),
  ('ry-cox-l4', 'ry-coxluq', 'Çoxluqların birləşməsi (∪)', 'İki çoxluğun bütün elementləri — birləşmə.', null, '[{"heading":"Birləşmə nədir?","body":"İki çoxluğun BÜTÜN elementlərindən (heç birini təkrarlamadan) düzələn çoxluğa onların birləşməsi deyilir və A ∪ B ilə işarələnir."},{"heading":"Nümunə","body":"A = {1, 2, 3}, B = {3, 4, 5} olsa, A ∪ B = {1, 2, 3, 4, 5}. Ortaq element (3) yalnız bir dəfə yazılır."},{"heading":"Qayda","body":"Birləşmədə hər iki çoxluğun elementlərini bir yerə yığırıq. Təkrarlanan element cəmi bir dəfə götürülür."}]'::jsonb, 3)
